#include <algorithm>
using namespace std;

int Cost(int numOfCity, int tank)
{
    int trips = numOfCity - 1;
    tank = min(tank, trips);

    int money = tank;
    for (int city = 2; city <= numOfCity - tank; ++city)
        money += city;

    return money;
}

